style.css:
@-moz-document domain("youtube.com") {
/* General background & text color */
  body, ytd-app, #page-manager {
    background-color: #000 !important;
    color: #f90 !important;
    font-family: "Segoe UI", Tahoma, Geneva, Verdana, sans-serif !important;
  }

  /* Header and top bar */
  #masthead, ytd-masthead, tp-yt-app-header {
    background-color: #111 !important;
    border-bottom: 2px solid #f90 !important;
  }

  /* Search box */
  input#search, ytd-searchbox input {
    background-color: #222 !important;
    color: #f90 !important;
    border: 1px solid #f90 !important;
  }

  /* Sidebar */
  #guide-content, ytd-guide-renderer {
    background-color: #111 !important;
  }

  /* Thumbnails & video containers */
  ytd-thumbnail, ytd-video-renderer, ytd-rich-item-renderer {
    background-color: #111 !important;
    border-radius: 5px;
    transition: 0.3s ease;
  }

  ytd-thumbnail:hover {
    transform: scale(1.02);
    box-shadow: 0 0 10px #f90;
  }

  /* Text colors */
  a, h3, yt-formatted-string, #video-title {
    color: #f90 !important;
  }

  a:hover, yt-formatted-string:hover {
    color: #fff !important;
  }

  /* Buttons */
  tp-yt-paper-button, ytd-toggle-button-renderer, ytd-subscribe-button-renderer {
    color: #000 !important;
    background-color: #f90 !important;
    border-radius: 3px !important;
    font-weight: bold !important;
  }

  /* Video player */
  .ytp-chrome-bottom, .ytp-chrome-top {
    background: rgba(0, 0, 0, 0.8) !important;
  }

  .ytp-play-button, .ytp-button {
    filter: hue-rotate(30deg) brightness(1.5);
  }

  /* Replace YouTube logo with Pornhub logo */
  #logo-icon {
    display: none !important;
  }

  #logo {
    background-image: url("https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Pornhub-logo.svg/512px-Pornhub-logo.svg.png");
    background-size: contain;
    background-repeat: no-repeat;
    height: 30px !important;
    width: 120px !important;
  }

  #logo a {
    display: block !important;
    height: 100% !important;
    width: 100% !important;
  }
}
